import type { WixDataIsReferencedOptions } from './types'

/**
 * Options builder for isReferenced operations.
 *
 * Use this builder to configure whether the reference check uses a consistent read.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataIsReferencedOptionsBuilder {
  /**
   * Sets whether the reference check uses a consistent read.
   */
  withConsistentRead(value: boolean): WixDataIsReferencedOptionsBuilder
  /**
   * Builds the isReferenced options object.
   */
  build(): WixDataIsReferencedOptions
}

class WixDataIsReferencedOptionsBuilderImpl
  implements WixDataIsReferencedOptionsBuilder
{
  constructor(private readonly options: WixDataIsReferencedOptions = {}) {}

  withConsistentRead(value: boolean): WixDataIsReferencedOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  build(): WixDataIsReferencedOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataIsReferencedOptions
  ): WixDataIsReferencedOptionsBuilder {
    return new WixDataIsReferencedOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new isReferenced options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an isReferenced options builder"
 * import { items, IsReferencedOptionsBuilder } from '@wix/data'
 *
 * const options = IsReferencedOptionsBuilder()
 *   .withConsistentRead(true)
 *   .build()
 *
 * const isReferenced = await items.isReferenced(
 *   'myCollection',
 *   'someField',
 *   'referringItemId',
 *   'referencedItemId',
 *   options
 * )
 * ```
 */
export const IsReferencedOptionsBuilder: () => WixDataIsReferencedOptionsBuilder =
  () => new WixDataIsReferencedOptionsBuilderImpl()
